"""Human/model semantic review, not keyword classification. Each row is individually reviewed.
Episodes can collapse repeated attacks. Their count is not an exact count of arena attempts.
Syntax family:outcome:source selectors. Context text preserves the preceding decision caveat.
"""
REVIEWS = {}
def a(alias, episodes, assessment, death='enemy_before_friendly', context=None):
    REVIEWS[alias] = dict(episodes=episodes, assessment=assessment, death=death, context=context or {})

